#include <queue>
#include <iostream>

int main() {
    std::priority_queue<int> q;
    q.push(10);
    q.push(20);

    // Safe access and removal sequence
    if (!q.empty()) {
        std::cout << "Highest: " << q.top() << '\n'; // Access
        q.pop();                                 // Remove (O(log N))
    }

    // Draining the queue safely
    while (!q.empty()) {
        q.pop(); 
    }

    // q.top(); // DANGER: Undefined Behavior if executed here
}
